sys_variable_value.value:
(function(outputs, steps, stepResult, assertEqual)
{
	var test = new x_snc_devtools.TestAPI(outputs, steps, stepResult, assertEqual);
	
	test.SetResult(true);
	
	function TestCase_MakePascalCase(strInput,vExpected)
	{
		function TestCase_MakePascalCase_CheckResult(vInput,vExpected,vResult)
		{
			return (vExpected == vResult);
		}
		
		test.TestCase(
			'Function MakePascalCase()',
			MakePascalCase,
			{
				'strInput': strInput
			},
			vExpected,
			TestCase_MakePascalCase_CheckResult);
	}
		
	TestCase_MakePascalCase(null,'');
	TestCase_MakePascalCase('','');
	TestCase_MakePascalCase(' ','');

	TestCase_MakePascalCase('hello World','HelloWorld');
	TestCase_MakePascalCase('HelloWorld','HelloWorld');
	TestCase_MakePascalCase('hello_world','HelloWorld');
	TestCase_MakePascalCase('hello-world','HelloWorld');
	TestCase_MakePascalCase('hello.world','HelloWorld');
	TestCase_MakePascalCase('hello/world','HelloWorld');
	TestCase_MakePascalCase('hello\tworld','HelloWorld');
	TestCase_MakePascalCase('HELLO_WORLD','HELLOWORLD');
	
	TestCase_MakePascalCase('42 is the answer','42IsTheAnswer');
	TestCase_MakePascalCase('11-friends','11Friends');
	TestCase_MakePascalCase('sense 8','Sense8');
	TestCase_MakePascalCase('one-2-one','One2One');

	TestCase_MakePascalCase('héllo\tworld','HélloWorld');
	TestCase_MakePascalCase('âllo\tworld','ÂlloWorld');

	return test.GetResult();
	
})(outputs, steps, stepResult, assertEqual);
